        # Split off pre-release
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # Convert identifiers to comparable form
        def to_comparable(identifier):
            if identifier.isdigit():
                return (0, int(identifier))
            else:
                return (1, identifier)

        pre1_comparable = [to_comparable(id) for id in pre1]
        pre2_comparable = [to_comparable(id) for id in pre2]

        # Compare left to right
        for i in range(min(len(pre1_comparable), pre2_comparable)):
            if pre1_comparable[i] != pre2_comparable[i]:
                return pre1_comparable[i] < pre2_comparable[i]

        # If all shared identifiers are equal, fewer identifiers sorts first
        return len(pre1_comparable) < len(pre2_comparable)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)

        # Pre-release versions sort before release versions
        # Empty prerelease list means it's a release version
        if prerelease:
            # Has pre-release: (major, minor, patch, 0, prerelease_tuple)
            prerelease_tuple = tuple(
                (0, int(id)) if id.isdigit() else (1, id)
                for id in prerelease
            )
            return (major, minor, patch, 0, prerelease_tuple, index)
        else:
            # No pre-release (release version): (major, minor, patch, 1)
            return (major, minor, patch, 1, (), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [version for _, version in sorted_versions]

